class CustomerDao:
    def __init__(self, session: Session) -> None:  # sessionmaker at module scope
        self._session = session

    def find(self, customer_id: int) -> Customer | None:
        return self._session.get(Customer, customer_id)      # identity map first

    def by_email(self, email: str) -> list[Customer]:
        return list(self._session.scalars(
            select(Customer).where(Customer.email == email)))  # 2.0 style, no Query
